INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 0.0, 24001, 10046, 0.0, 102301, "アヤネ", 2, 401, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 0.0, 24002, 10046, 2.21, 102301, "アヤネ", 1, 402, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 0.0, 24003, 10046, 0.0, 102301, "アヤネ", 2, 403, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 0.0, 24004, 10046, 1.99, 192201, "アサヒ", 2, 701, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 0.0, 24005, 10046, 2.21, 192201, "アサヒ", 1, 702, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 0.0, 24006, 10046, 3.33, 192201, "アサヒ", 2, 703, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 0.0, 24007, 10046, 0.0, 192301, "部員３", 2, 801, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 0.0, 24008, 10046, 2.68, 192301, "部員３", 1, 802, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 0.0, 24009, 10046, 0.0, 192301, "部員３", 2, 803, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "やった！", 0.0, 24010, 10046, 0.0, 192501, "", 1, 501, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "勝ったよ！", 0.0, 24011, 10046, 0.0, 192501, "", 1, 502, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "いい調子！", 0.0, 24012, 10046, 0.0, 192501, "", 1, 503, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 0.0, 24013, 10046, 5.33, 113501, "ミサト", 6, 111, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 0.0, 24014, 10046, 6.85, 113501, "ミサト", 1, 112, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 0.0, 24015, 10046, 3.0, 113501, "ミサト", 1, 113, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 0.0, 24016, 10046, 6.11, 192401, "ダイチ", 1, 611, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 0.0, 24017, 10046, 6.75, 192401, "ダイチ", 1, 612, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 0.0, 24018, 10046, 0.0, 192401, "ダイチ", 2, 613, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 0.0, 24019, 10046, 4.52, 113401, "ハツネ", 2, 211, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 0.0, 24020, 10046, 3.89, 113401, "ハツネ", 2, 212, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 0.0, 24021, 10046, 13.49, 113401, "ハツネ", 1, 213, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 0.0, 24022, 10046, 3.17, 106501, "カヤ", 1, 311, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 0.0, 24023, 10046, 4.42, 106501, "カヤ", 1, 312, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 0.0, 24024, 10046, 2.89, 106501, "カヤ", 6, 313, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 3, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 0.0, 24025, 10046, 3.71, 102301, "アヤネ", 4, 421, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 0.0, 24026, 10046, 5.1, 192201, "アサヒ", 2, 721, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 3, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 0.0, 24027, 10046, 4.34, 192301, "部員３", 1, 821, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "いい勝負だったよ\nまたやろうね", 0.0, 24028, 10046, 0.0, 192501, "", 1, 521, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 0.0, 24029, 10046, 5.62, 113501, "ミサト", 1, 101, "2020/07/31 12:00:00", "2030/12/17 14:59:59", -360.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 0.0, 24030, 10046, 9.58, 113501, "ミサト", 1, 102, "2020/07/31 12:00:00", "2030/12/17 14:59:59", -360.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 0.0, 24031, 10046, 0.0, 113501, "ミサト", 2, 103, "2020/07/31 12:00:00", "2030/12/17 14:59:59", -360.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 1, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 0.0, 24032, 10046, 9.13, 113501, "ミサト", 2, 104, "2020/07/31 12:00:00", "2030/12/17 14:59:59", -360.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (24, 2, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 0.0, 24033, 10046, 8.27, 113501, "ミサト", 1, 105, "2020/07/31 12:00:00", "2030/12/17 14:59:59", -360.0);
